/// Every colour that flips between light and dark mode. Widgets take a
/// `const Palette&` rather than reading a global, so the theme cross-fade
/// can paint the same widget twice with two different palettes.
struct Palette {
    Color bg;
    Color card;
    Color text;
    Color muted;
    Color border;
    Color divider;
    Color accent;
    Color accentSoft;
    Color accentText;
    Color surfaceSunken;
    Color hover;
    Color danger;
    Color shadow;
    Color ring;
    Color pageShadow;
    /// True past the midpoint of a theme cross-fade. A hard boolean:
    /// anything that must move smoothly through a transition should
    /// use darkness() below instead, not this.
    bool isDark = false;
};

/// 0 for a white background, 1 for a black one. Continuous across a
/// theme cross-fade because it reads the already-interpolated colour,
/// so code that used to branch on isDark can lerp on this and stop
/// popping at the halfway point.
[[nodiscard]] inline float darkness(const Palette& p) noexcept {
    const float lum = (0.299f * static_cast<float>(p.bg.r) +
                       0.587f * static_cast<float>(p.bg.g) +
                       0.114f * static_cast<float>(p.bg.b)) /
                      255.f;
    return 1.f - lum;
}

